1	/**
2	 * Turns the session cookie into an `Actor`. Everything server-side that needs authorization starts here.
3	 *
4	 * Must call (do not reimplement): assertOrgScope
5	 */
6	import { hashToken, randomToken } from "@/lib/hash";
7	import { assertOrgScope } from "@/lib/tenant";
8	import * as memberRepo from "@/server/repositories/member-repository";
9	import * as orgRepo from "@/server/repositories/organization-repository";
10	import * as sessionRepo from "@/server/repositories/session-repository";
11	import { toIsoTimestamp } from "@/types/common";
12	import type { SwitchOrgInput } from "@/schemas/session";
13	import type { IsoTimestamp, UserId } from "@/types/common";
14	import type { Actor, SessionPrincipal } from "@/types/member";
15	
16	/** How long a freshly issued session cookie stays valid. */
17	const SESSION_TTL_DAYS = 30;
18	const MS_PER_DAY = 24 * 60 * 60 * 1000;
19	
20	/** Length in bytes of the raw session token handed to the browser. */
21	const TOKEN_BYTES = 32;
22	
23	/**
24	 * Mints a session. Only the hash reaches the database, so a dump of the
25	 * `sessions` table cannot be replayed as a login.
26	 */
27	export async function createSessionToken(
28	  userId: UserId,
29	): Promise<{ token: string; expiresAt: IsoTimestamp }> {
30	  const token = randomToken(TOKEN_BYTES);
31	  const expiresAt = toIsoTimestamp(
32	    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
33	  );
34	
35	  await sessionRepo.createSession(userId, hashToken(token), expiresAt);
36	
37	  return { token, expiresAt };
38	}
39	
40	export async function resolveSession(
41	  token: string,
42	): Promise<SessionPrincipal | null> {
43	  return sessionRepo.findSessionByTokenHash(hashToken(token));
44	}
45	
46	/**
47	 * The bridge between "who is logged in" and "what may they do here": given a
48	 * principal and the org slug in the URL, produce the `Actor` every service
49	 * method takes, or `null` when the user is not a member of that org.
50	 *
51	 * The `assertOrgScope` call at the end looks redundant — the actor was just
52	 * built from that org — but it is the invariant this whole layer exists to
53	 * uphold, and it catches a mis-wired membership lookup immediately.
54	 */
55	export async function resolveActorForOrg(
56	  principal: SessionPrincipal,
57	  orgSlug: string,
58	): Promise<Actor | null> {
59	  // Same lookup as `OrganizationService.resolveOrgBySlug`, taken from the
60	  // repository directly to keep the session layer free of the service layer.
61	  const org = await orgRepo.findOrgBySlug(orgSlug);
62	  if (!org) return null;
63	
64	  const member = await memberRepo.findMember(org.id, principal.userId);
65	  if (!member || member.status !== "active") return null;
66	
67	  const actor: Actor = {
68	    userId: principal.userId,
69	    orgId: org.id,
70	    role: member.role,
71	  };
72	
73	  assertOrgScope(actor, org.id);
74	
75	  await memberRepo.touchLastSeen(
76	    org.id,
77	    principal.userId,
78	    toIsoTimestamp(new Date()),
79	  );
80	
81	  return actor;
82	}
83	
84	/**
85	 * Switches the org a session defaults to. Membership is re-checked here so a
86	 * removed member cannot pin their cookie to an org they left.
87	 *
88	 * `SessionPrincipal` carries no session id, so the write to `sessions.
89	 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
90	 * Action, which still holds the cookie. This method owns the authorization
91	 * half of the switch.
92	 */
93	export async function switchActiveOrg(
94	  principal: SessionPrincipal,
95	  input: SwitchOrgInput,
96	): Promise<void> {
97	  const member = await memberRepo.findMember(input.orgId, principal.userId);
98	  if (!member || member.status !== "active") {
99	    throw new Error("You are not a member of that organization");
100	  }
101	
102	  const orgs = await orgRepo.listOrgsForUser(principal.userId);
103	  const target = orgs.find((org) => org.id === input.orgId);
104	  if (!target) throw new Error("You are not a member of that organization");
105	
106	  assertOrgScope(
107	    { userId: principal.userId, orgId: input.orgId, role: member.role },
108	    target.id,
109	  );
110	}
111	
112	/**
113	 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
114	 * exposes no session id, so the sweep is what actually clears the row, and the
115	 * cookie is dropped by the caller either way.
116	 */
117	export async function destroySession(token: string): Promise<void> {
118	  const principal = await resolveSession(token);
119	  if (!principal) return;
120	
121	  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
122	}
