/**
 * Private row → domain mappers for the repository layer.
 *
 * SQLite stores branded ids as plain text and collections as JSON strings, so
 * exactly one place is allowed to re-apply the brands and parse the JSON: here.
 * Services never see a `*Row` type.
 */
import type {
  ActivityEventRow,
  AttachmentRow,
  CommentRow,
  InvitationRow,
  InvoiceRow,
  IssueRow,
  LabelRow,
  MemberRow,
  NotificationPreferenceRow,
  NotificationRow,
  OrganizationRow,
  OrganizationUsageRow,
  ProjectRow,
  SubscriptionRow,
  UserRow,
} from "@/server/db";
import type {
  ActivityAction,
  ActivityEvent,
} from "@/types/activity";
import type { Invoice, Subscription } from "@/types/billing";
import type { Comment } from "@/types/comment";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
  OrgId,
  ProjectId,
  SubscriptionId,
  UserId,
} from "@/types/common";
