import { and, eq, gt, isNull, like, ne } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations, orgRetiredSlugs } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** ISO instant before which a retirement has expired and the slug is released. */
function holdCutoff(): string {
  return toIsoTimestamp(new Date(Date.now() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY));
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Resolves a slug to its workspace, the way every slug lookup must: the
 * current slug first, then a still-held retired slug (see
 * `docs/adr/0005-workspace-urls.md`).
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const current = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (current) return toOrganization(current);

  const retired = getDb()
    .select({ orgId: orgRetiredSlugs.orgId })
    .from(orgRetiredSlugs)
    .where(and(eq(orgRetiredSlugs.slug, slug), gt(orgRetiredSlugs.retiredAt, holdCutoff())))
    .get();
  if (!retired) return null;

  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.id, retired.orgId), isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Whether `slug` may become `orgId`'s new current slug: free from every other
 * workspace's current slug, and from every other workspace's still-held
 * retirement. A slug this workspace itself retired is always available to it.
 */
export async function isSlugAvailableForRename(
  orgId: OrgId,
  slug: string,
): Promise<boolean> {
  const takenAsCurrent = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (takenAsCurrent) return false;

  const heldByOther = getDb()
    .select({ id: orgRetiredSlugs.id })
    .from(orgRetiredSlugs)
    .where(
      and(
        eq(orgRetiredSlugs.slug, slug),
        ne(orgRetiredSlugs.orgId, orgId),
        gt(orgRetiredSlugs.retiredAt, holdCutoff()),
      ),
    )
    .get();

  return !heldByOther;
}

/**
 * Renames `orgId`'s slug: writes the new current slug, retires the old one,
 * and ends the new slug's own retirement if this workspace previously
 * retired it (renaming back).
 */
export async function renameOrgSlug(
  orgId: OrgId,
  newSlug: string,
  previousSlug: string,
): Promise<Organization> {
  const stamp = toIsoTimestamp(new Date());

  getDb()
    .delete(orgRetiredSlugs)
    .where(and(eq(orgRetiredSlugs.orgId, orgId), eq(orgRetiredSlugs.slug, newSlug)))
    .run();

  getDb()
    .insert(orgRetiredSlugs)
    .values({ id: newId(), orgId, slug: previousSlug, retiredAt: stamp })
    .run();

  const row = getDb()
    .update(organizations)
    .set({ slug: newSlug, updatedAt: stamp })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

