/**
 * Changes a workspace's URL slug. See `docs/adr/0005-workspace-urls.md`: the
 * slug is taken as given (never suffixed), unavailable slugs are refused, a
 * rename to the current slug is a no-op, and the old slug keeps resolving for
 * `ORG_SLUG_HOLD_DAYS` days rather than releasing immediately.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (input.slug === org.slug) return org;

  assertValidSlug(input.slug);

  const available = await orgRepo.isSlugAvailableForRename(input.orgId, input.slug);
  if (!available) {
    throw new InvalidSlugError(input.slug, "is taken");
  }

  const previousSlug = org.slug;
  const updated = await orgRepo.renameOrgSlug(input.orgId, input.slug, previousSlug);

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: previousSlug,
    to: input.slug,
  });

  await record(input.orgId, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `URL changed from ${previousSlug} to ${input.slug}`,
    metadata: { from: previousSlug, to: input.slug },
  });

  return updated;
}

